sa="stbootcamp$RANDOM"
az storage container create --account-name $sa --name imagery --auth-mode login
echo "survey flight 042" > flight042.txt
az storage blob upload --account-name $sa --container-name imagery \
  --file flight042.txt --auth-mode login
cat > lifecycle.json <<'EOF'
{
  "rules": [{
    "name": "tier-aging-imagery", "enabled": true, "type": "Lifecycle",
    "definition": {
      "filters": { "blobTypes": ["blockBlob"], "prefixMatch": ["imagery/raw/"] },
      "actions": { "baseBlob": { "tierToCool": { "daysAfterModificationGreaterThan": 30 } } }
    }
  }]
}
EOF

