terraform {
  backend "s3" {
    bucket         = "civicworks-tfstate-<yours>"
    key            = "civicworks/terraform.tfstate"
    region         = "us-east-1"
    dynamodb_table = "civicworks-tf-locks"
    encrypt        = true
  }
}

